.daily-usage { min-width: 0px; }.daily-usage__balance { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 12px; margin: 12px 0px 20px; }.daily-usage__balance strong { font-size: 28px; font-variant-numeric: tabular-nums; }.daily-usage__balance small { width: 100%; color: var(--color-text-muted); }.daily-usage__controls { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 4px 0px 12px; font-size: 13px; }.daily-usage__controls button, .daily-usage__controls select { padding: 6px; border: 1px solid var(--color-border); border-radius: 6px; color: inherit; background: transparent; }.daily-usage__controls button { display: flex; cursor: pointer; }.daily-usage__controls button:disabled { opacity: 0.4; cursor: default; }.daily-usage__controls label { margin-left: auto; }.daily-usage__muted { font-size: 12px; color: var(--color-text-secondary); line-height: 1.6; }.daily-usage__legend { display: flex; flex-wrap: wrap; gap: 8px 20px; font-size: 12px; color: var(--color-text-secondary); }.daily-usage__legend span::before { content: ""; display: inline-block; width: 9px; height: 9px; margin-right: 6px; border-radius: 2px; background: var(--color-accent, #6366f1); }.daily-usage__legend .daily-usage__returned::before, .daily-usage__bar.daily-usage__returned { background: rgb(22, 163, 74); }.daily-usage__graph { display: grid; grid-template-columns: 48px minmax(0px, 1fr); grid-template-rows: 160px auto; margin: 20px 0px 12px; }.daily-usage__y-axis { position: relative; font-size: 11px; color: var(--color-text-secondary); font-variant-numeric: tabular-nums; }.daily-usage__y-axis span { position: absolute; right: 8px; transform: translateY(-50%); }.daily-usage__chart { position: relative; display: flex; min-width: 0px; gap: 1px; }.daily-usage__grid { position: absolute; inset: 0px; pointer-events: none; }.daily-usage__grid span { position: absolute; left: 0px; right: 0px; border-top: 1px solid var(--color-border); }.daily-usage__chart > button { position: relative; flex: 1 1 0px; min-width: 0px; padding: 0px; background: transparent; border: 0px; border-radius: 3px; color: inherit; cursor: pointer; }.daily-usage__chart > button:hover, .daily-usage__chart > button[aria-pressed="true"] { background: color-mix(in srgb,var(--color-accent, #6366f1) 10%,transparent); outline: 1px solid var(--color-accent, #6366f1); }.daily-usage button:focus-visible, .daily-usage summary:focus-visible, .daily-usage select:focus-visible { outline: 2px solid var(--color-accent, #6366f1); outline-offset: 2px; }.daily-usage__bar { position: absolute; bottom: 0px; left: 10%; right: 10%; background: var(--color-accent, #6366f1); border-radius: 2px 2px 0px 0px; }.daily-usage__x-axis { grid-column: 2; display: flex; justify-content: space-between; gap: 4px; padding-top: 10px; font-size: 11px; color: var(--color-text-secondary); }.daily-usage__x-axis span { white-space: nowrap; }.daily-usage__detail { border-top: 1px solid var(--color-border); margin-top: 12px; padding-top: 12px; }.daily-usage__detail h3 { margin: 4px 0px 14px; font-size: 16px; }.daily-usage__totals { display: flex; flex-wrap: wrap; gap: 12px 24px; margin: 12px 0px; }.daily-usage__totals dt { font-size: 12px; color: var(--color-text-secondary); }.daily-usage__totals dd { margin: 4px 0px 0px; font-size: 17px; font-weight: 600; font-variant-numeric: tabular-nums; }.daily-usage__project { border: 1px solid var(--color-border); border-radius: 8px; margin-top: 10px; overflow-wrap: anywhere; }.daily-usage__project summary { cursor: pointer; padding: 14px; font-size: 13px; }.daily-usage__project summary > span:last-child { float: right; margin-left: 12px; color: var(--color-text-secondary); }.daily-usage__project-body { padding: 0px 14px 12px; }.daily-usage__project-body > a { font-size: 12px; }.daily-usage__tasks { list-style: none; margin: 12px 0px 0px; padding: 0px; }.daily-usage__tasks > li { padding: 14px 0px 8px; border-top: 1px solid var(--color-border); font-size: 13px; }.daily-usage__tasks .daily-usage__totals dd { font-size: 14px; }.daily-usage__adjustment { font-size: 12px; line-height: 1.5; }@media (max-width: 600px) {
  .daily-usage__controls label { margin-left: 0px; }
