}.daily-usage__balance { margin: 4px 0px 20px; padding: 14px 16px; border: 1px solid var(--color-border-light, var(--color-border)); border-radius: 12px; }.daily-usage__balance strong { font-size: 32px; font-weight: 600; line-height: 1.1; }.daily-usage__balance > span { font-size: 13.5px; color: var(--color-text-secondary); }.daily-usage__balance--empty { border-color: color-mix(in srgb,var(--color-brand, #f02d5e) 40%,var(--color-border)); }.daily-usage__balance--empty strong, .daily-usage__balance--empty > span { color: var(--color-brand, #f02d5e); }

